/**
 * Prisma Seed — Core Master Data
 *
 * Source of truth: reference_source/import/ (generated by TASK-008 pipeline)
 * Manifest hash:   ef0589fbafc22afbb1ee21556d0de615cf1e8df3092216622ad015f5a4fc4a7d
 *
 * Seeds the following entities from APPROVED reference data only:
 *   - Permissions (from ROLE_PERMISSION.md)
 *   - Roles       (SUPER_ADMIN, ADMIN, MARKETING)
 *   - RolePermissions (matrix from ROLE_PERMISSION.md §4)
 *   - BPRs
 *   - Products
 *   - CreditParameters
 *   - FeeParameters
 *   - InsuranceRates
 *   - PaymentOffices
 *   - BusinessRuleVersion (BR-1.0)
 *   - ParameterVersion    (v1.0 per product)
 *
 * Rules:
 *   - No data is invented or approximated.
 *   - All numeric financial values read directly from approved JSON artifacts.
 *   - Idempotent: uses upsert on unique keys, safe to re-run.
 */

import { PrismaClient } from "@prisma/client";
import * as fs from "fs";
import * as path from "path";

const prisma = new PrismaClient();

// ---------------------------------------------------------------------------
// Load approved import artifacts
// ---------------------------------------------------------------------------
const IMPORT_DIR = path.resolve(__dirname, "../reference_source/import");
const MANIFEST_PATH = path.join(IMPORT_DIR, "manifest.json");

function loadImport<T>(filename: string): T[] {
  const filePath = path.join(IMPORT_DIR, filename);
  if (!fs.existsSync(filePath)) {
    throw new Error(
      `BLOCKED: Approved import file not found: ${filePath}. Run the import pipeline first.`
    );
  }
  return JSON.parse(fs.readFileSync(filePath, "utf-8")) as T[];
}

function verifyManifest() {
  if (!fs.existsSync(MANIFEST_PATH)) {
    throw new Error(
      "BLOCKED: manifest.json not found in reference_source/import/. Run the import pipeline first."
    );
  }
  const manifest = JSON.parse(fs.readFileSync(MANIFEST_PATH, "utf-8"));
  if (manifest.validationStatus !== "APPROVED") {
    throw new Error(
      `BLOCKED: Import manifest status is "${manifest.validationStatus}", not "APPROVED". Validation must pass before seeding.`
    );
  }
  console.log(`✅ Manifest verified — Source hash: ${manifest.documentHash}`);
  console.log(`   Pipeline version: ${manifest.pipelineVersion}`);
  console.log(`   Extracted at:     ${manifest.extractedAt}`);
  return manifest;
}

