// ---------------------------------------------------------------------------
// Role-Permission matrix — from ROLE_PERMISSION.md §4
// ---------------------------------------------------------------------------
const SUPER_ADMIN_PERMISSIONS = [
  "AUTH_LOGIN", "AUTH_LOGOUT", "AUTH_CHANGE_PASSWORD", "AUTH_RESET_PASSWORD",
  "PROFILE_VIEW", "PROFILE_UPDATE",
  "USER_VIEW", "USER_CREATE", "USER_UPDATE", "USER_DELETE", "USER_ACTIVATE",
  "USER_DEACTIVATE", "USER_RESET_PASSWORD", "USER_ASSIGN_ROLE",
  "ROLE_VIEW", "ROLE_CREATE", "ROLE_UPDATE", "ROLE_DELETE",
  "PERMISSION_VIEW", "ROLE_PERMISSION_ASSIGN",
  "CREDIT_CALCULATE", "CREDIT_VIEW_RESULT", "CREDIT_EXPORT",
  "SIMULATION_VIEW", "SIMULATION_CREATE", "SIMULATION_UPDATE",
  "SIMULATION_DELETE", "SIMULATION_EXPORT",
  "MASTER_VIEW", "MASTER_CREATE", "MASTER_UPDATE", "MASTER_DELETE",
  "CREDIT_PARAMETER_VIEW", "CREDIT_PARAMETER_CREATE", "CREDIT_PARAMETER_UPDATE",
  "CREDIT_PARAMETER_DELETE",
  "REPORT_VIEW", "REPORT_EXPORT",
  "AUDIT_VIEW", "AUDIT_EXPORT",
];

const ADMIN_PERMISSIONS = [
  "AUTH_LOGIN", "AUTH_LOGOUT", "AUTH_CHANGE_PASSWORD", "AUTH_RESET_PASSWORD",
  "PROFILE_VIEW", "PROFILE_UPDATE",
  "USER_VIEW", "USER_CREATE", "USER_UPDATE", "USER_ACTIVATE",
  "USER_DEACTIVATE", "USER_RESET_PASSWORD", "USER_ASSIGN_ROLE",
  "CREDIT_CALCULATE", "CREDIT_VIEW_RESULT", "CREDIT_EXPORT",
  "SIMULATION_VIEW", "SIMULATION_CREATE", "SIMULATION_UPDATE",
  "SIMULATION_DELETE", "SIMULATION_EXPORT",
  "MASTER_VIEW", "MASTER_CREATE", "MASTER_UPDATE", "MASTER_DELETE",
  "CREDIT_PARAMETER_VIEW", "CREDIT_PARAMETER_CREATE", "CREDIT_PARAMETER_UPDATE",
  "REPORT_VIEW", "REPORT_EXPORT",
  "AUDIT_VIEW",
];

const MARKETING_PERMISSIONS = [
  "AUTH_LOGIN", "AUTH_LOGOUT", "AUTH_CHANGE_PASSWORD",
  "PROFILE_VIEW", "PROFILE_UPDATE",
  "CREDIT_CALCULATE", "CREDIT_VIEW_RESULT", "CREDIT_EXPORT",
  "SIMULATION_VIEW", "SIMULATION_CREATE", "SIMULATION_UPDATE",
  "SIMULATION_DELETE", "SIMULATION_EXPORT",
  "REPORT_VIEW", "REPORT_EXPORT",
];

// ---------------------------------------------------------------------------
// Main seed function
// ---------------------------------------------------------------------------
async function main() {
  console.log("\n🌱 Starting TASK-009 — Core Master Data Seed...\n");

  // 1. Verify approved manifest before any seeding
  const manifest = verifyManifest();

  // -------------------------------------------------------------------------
  // 2. Seed Permissions
  // -------------------------------------------------------------------------
  console.log(`\n📌 Seeding ${PERMISSIONS.length} permissions...`);
  for (const perm of PERMISSIONS) {
    await prisma.permission.upsert({
      where: { code: perm.code },
      update: { name: perm.name, module: perm.module },
      create: { code: perm.code, name: perm.name, module: perm.module },
    });
  }
  console.log(`   ✅ ${PERMISSIONS.length} permissions upserted.`);

  // -------------------------------------------------------------------------
  // 3. Seed Roles
  // -------------------------------------------------------------------------
  console.log("\n📌 Seeding roles (SUPER_ADMIN, ADMIN, MARKETING)...");
  const roles = [
    { code: "SUPER_ADMIN", name: "Super Admin",  description: "Akses penuh ke seluruh sistem" },
    { code: "ADMIN",       name: "Admin",         description: "Akses operasional sesuai scope" },
    { code: "MARKETING",   name: "Marketing",     description: "Pengguna operasional simulasi kredit" },
  ];
  const roleMap: Record<string, string> = {};
  for (const role of roles) {
    const r = await prisma.role.upsert({
      where: { code: role.code },
      update: { name: role.name, description: role.description, isActive: true },
      create: { code: role.code, name: role.name, description: role.description, isActive: true },
    });
    roleMap[role.code] = r.id;
  }
  console.log(`   ✅ 3 roles upserted.`);

  // -------------------------------------------------------------------------
  // 4. Seed Role-Permissions
  // -------------------------------------------------------------------------
  console.log("\n📌 Seeding role-permission assignments...");
  const permMap: Record<string, string> = {};
  const allPerms = await prisma.permission.findMany({ select: { id: true, code: true } });
  for (const p of allPerms) {
    permMap[p.code] = p.id;
  }

  const rolePermMatrix = [
    { roleCode: "SUPER_ADMIN", permCodes: SUPER_ADMIN_PERMISSIONS },
    { roleCode: "ADMIN",       permCodes: ADMIN_PERMISSIONS },
    { roleCode: "MARKETING",   permCodes: MARKETING_PERMISSIONS },
  ];

  let rpCount = 0;
  for (const { roleCode, permCodes } of rolePermMatrix) {
    const roleId = roleMap[roleCode];
    for (const permCode of permCodes) {
      const permId = permMap[permCode];
      if (!permId) {
        console.warn(`   ⚠️  Permission code not found: ${permCode}`);
        continue;
      }
      await prisma.rolePermission.upsert({
        where: { roleId_permissionId: { roleId, permissionId: permId } },
        update: {},
        create: { roleId, permissionId: permId },
      });
      rpCount++;
    }
  }
  console.log(`   ✅ ${rpCount} role-permission assignments upserted.`);

  // -------------------------------------------------------------------------
  // 5. Seed BPRs
  // -------------------------------------------------------------------------
  const bprData = loadImport<{ code: string; name: string; status: string }>("bpr_master.json");
  console.log(`\n📌 Seeding ${bprData.length} BPRs...`);
  const bprMap: Record<string, string> = {};
  for (const bpr of bprData) {
    const b = await prisma.bpr.upsert({
      where: { code: bpr.code },
      update: { name: bpr.name, status: bpr.status },
      create: { code: bpr.code, name: bpr.name, status: bpr.status },
    });
    bprMap[bpr.code] = b.id;
  }
  console.log(`   ✅ ${bprData.length} BPRs upserted.`);

  // -------------------------------------------------------------------------
  // 6. Seed Products
  // -------------------------------------------------------------------------
  const productData = loadImport<{
    code: string; name: string; bprCode: string; description: string; status: string;
  }>("products.json");
  console.log(`\n📌 Seeding ${productData.length} products...`);
  const productMap: Record<string, string> = {};
  for (const prod of productData) {
    const bprId = bprMap[prod.bprCode];
    if (!bprId) throw new Error(`BLOCKED: BPR not found for product "${prod.code}": bprCode="${prod.bprCode}"`);
    const p = await prisma.product.upsert({
      where: { bprId_code: { bprId, code: prod.code } },
      update: { name: prod.name, description: prod.description, status: prod.status },
      create: { bprId, code: prod.code, name: prod.name, description: prod.description, status: prod.status },
    });
    productMap[prod.code] = p.id;
  }
  console.log(`   ✅ ${productData.length} products upserted.`);

  // -------------------------------------------------------------------------
  // 7. Seed BusinessRuleVersion (BR-1.0)
  // -------------------------------------------------------------------------
  console.log("\n📌 Seeding business rule version BR-1.0...");
  await prisma.businessRuleVersion.upsert({
    where: { version: "BR-1.0" },
    update: {},
    create: {
      version: "BR-1.0",
      name: "Credit Calculator BPR — Business Rules v1.0",
      description: "Initial business rules: flat rate 10.8% p.a., DBR 90%, tenor max 120 months, principal max Rp200jt",
      status: "ACTIVE",
      effectiveFrom: new Date("2026-01-01"),
    },
  });
  console.log(`   ✅ BusinessRuleVersion BR-1.0 upserted.`);

  // -------------------------------------------------------------------------
  // 8. Seed ParameterVersions
  // -------------------------------------------------------------------------
  console.log("\n📌 Seeding parameter versions...");
  for (const prod of productData) {
    const productId = productMap[prod.code];
    await prisma.parameterVersion.upsert({
      where: { productId_version: { productId, version: "v1.0" } },
      update: {},
      create: {
        version: "v1.0",
        productId,
        description: `Initial parameter set for ${prod.name} — source: ${manifest.sourceFileName} (hash: ${manifest.documentHash.slice(0, 12)}...)`,
        effectiveFrom: new Date("2026-01-01"),
        status: "ACTIVE",
      },
    });
  }
  console.log(`   ✅ ${productData.length} parameter version(s) upserted.`);

  // -------------------------------------------------------------------------
  // 9. Seed Credit Parameters
  // -------------------------------------------------------------------------
  const creditParams = loadImport<{
    productCode: string; maximumAgeYears: number; maximumAgeMonths: number;
    maximumTenorMonths: number; maximumPrincipal: number; maximumDbr: number;
    flatAnnualRate: number; flatMonthlyRate: number; principalRoundingIncrement: number;
    installmentDeductionPeriods: number; version: string;
  }>("credit_parameters.json");
  console.log(`\n📌 Seeding ${creditParams.length} credit parameter(s)...`);
  for (const cp of creditParams) {
    const productId = productMap[cp.productCode];
    if (!productId) throw new Error(`BLOCKED: Product not found for credit param: "${cp.productCode}"`);
    // Deactivate any existing active params first (versioned)
    await prisma.creditParameter.updateMany({
      where: { productId, isActive: true },
      data: { isActive: false },
    });
    await prisma.creditParameter.create({
      data: {
        productId,
        maximumAgeYears: cp.maximumAgeYears,
        maximumAgeMonths: cp.maximumAgeMonths,
        maximumTenorMonths: cp.maximumTenorMonths,
        maximumPrincipal: cp.maximumPrincipal,
        maximumDbr: cp.maximumDbr,
        flatAnnualRate: cp.flatAnnualRate,
        flatMonthlyRate: cp.flatMonthlyRate,
        principalRoundingIncrement: cp.principalRoundingIncrement,
        installmentDeductionPeriods: cp.installmentDeductionPeriods,
        effectiveFrom: new Date("2026-01-01"),
        version: cp.version,
        isActive: true,
      },
    });
  }
  console.log(`   ✅ ${creditParams.length} credit parameter(s) seeded.`);

  // -------------------------------------------------------------------------
  // 10. Seed Fee Parameters
  // -------------------------------------------------------------------------
  const feeParams = loadImport<{
    productCode: string; adminRate: number; provisionRate: number; verificationFee: number;
    flaggingFee: number; frontingRate: number; reserveRate: number; version: string;
  }>("fee_parameters.json");
  console.log(`\n📌 Seeding ${feeParams.length} fee parameter(s)...`);
  for (const fp of feeParams) {
    const productId = productMap[fp.productCode];
    if (!productId) throw new Error(`BLOCKED: Product not found for fee param: "${fp.productCode}"`);
    await prisma.feeParameter.updateMany({
      where: { productId, isActive: true },
      data: { isActive: false },
    });
    await prisma.feeParameter.create({
      data: {
        productId,
        adminRate: fp.adminRate,
        provisionRate: fp.provisionRate,
        verificationFee: fp.verificationFee,
        flaggingFee: fp.flaggingFee,
        frontingRate: fp.frontingRate,
        reserveRate: fp.reserveRate,
        effectiveFrom: new Date("2026-01-01"),
        version: fp.version,
        isActive: true,
      },
    });
  }
  console.log(`   ✅ ${feeParams.length} fee parameter(s) seeded.`);

  // -------------------------------------------------------------------------
  // 11. Seed Payment Offices
  // -------------------------------------------------------------------------
  const paymentOffices = loadImport<{
    code: string; name: string; bprCode: string; type: string; status: string;
  }>("payment_offices.json");
  console.log(`\n📌 Seeding ${paymentOffices.length} payment offices...`);
  for (const po of paymentOffices) {
    const bprId = bprMap[po.bprCode];
    if (!bprId) throw new Error(`BLOCKED: BPR not found for payment office "${po.code}": bprCode="${po.bprCode}"`);
    await prisma.paymentOffice.upsert({
      where: { bprId_code: { bprId, code: po.code } },
      update: { name: po.name, type: po.type, status: po.status },
      create: { bprId, code: po.code, name: po.name, type: po.type, status: po.status },
    });
  }
  console.log(`   ✅ ${paymentOffices.length} payment offices upserted.`);

  // -------------------------------------------------------------------------
  // 12. Seed Insurance Rates
  // -------------------------------------------------------------------------
  const insuranceRates = loadImport<{
    productCode: string; age: number; tenorYears: number; premiumRate: number; version: string;
  }>("insurance_rates.json");
  console.log(`\n📌 Seeding ${insuranceRates.length} insurance rate rows...`);
  const effectiveFrom = new Date("2026-01-01");
  let irCount = 0;
  for (const ir of insuranceRates) {
    const productId = productMap[ir.productCode];
    if (!productId) throw new Error(`BLOCKED: Product not found for insurance rate: "${ir.productCode}"`);
    await prisma.insuranceRate.upsert({
      where: {
        productId_age_tenorYears_effectiveFrom: {
          productId,
          age: ir.age,
          tenorYears: ir.tenorYears,
          effectiveFrom,
        },
      },
      update: { premiumRate: ir.premiumRate, version: ir.version, isActive: true },
      create: {
        productId,
        age: ir.age,
        tenorYears: ir.tenorYears,
        premiumRate: ir.premiumRate,
        effectiveFrom,
        version: ir.version,
        isActive: true,
      },
    });
    irCount++;
  }
  console.log(`   ✅ ${irCount} insurance rate rows upserted.`);

  // -------------------------------------------------------------------------
  // Summary
  // -------------------------------------------------------------------------
  console.log("\n🎉 TASK-009 — Core Master Seed completed successfully!\n");
  console.log("📊 Final counts in database:");
  console.log(`   Permissions:    ${await prisma.permission.count()}`);
  console.log(`   Roles:          ${await prisma.role.count()}`);
  console.log(`   RolePermissions:${await prisma.rolePermission.count()}`);
  console.log(`   BPRs:           ${await prisma.bpr.count()}`);
  console.log(`   Products:       ${await prisma.product.count()}`);
  console.log(`   Credit Params:  ${await prisma.creditParameter.count({ where: { isActive: true } })}`);
  console.log(`   Fee Params:     ${await prisma.feeParameter.count({ where: { isActive: true } })}`);
  console.log(`   Payment Offices:${await prisma.paymentOffice.count()}`);
  console.log(`   Insurance Rates:${await prisma.insuranceRate.count({ where: { isActive: true } })}`);
}

main()
  .catch((e) => {
    console.error("\n❌ Seed failed:", e.message);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
